/**
 * ShadowRoot 内注入的公共 CSS
 *
 * 设计系统对齐 program-quest-demo / program-backpack-demo：
 * - Design tokens: --bg / --border / --text / --text-secondary
 * - 按钮: 44px 圆形玻璃态 + backdrop-filter:blur(12px)
 * - 面板: rgba(8,8,12,0.92) + backdrop-filter:blur(16px) + border-radius:16px
 * - 图标: stroke-based SVG (fill:none, stroke:currentColor)
 */
export const OFFICIAL_UI_STYLES = `
  /* ===== Design tokens（与 demo 对齐） ===== */
  :host {
    --bg: rgba(8, 8, 12, 0.92);
    --bg-btn: rgba(8, 8, 12, 0.8);
    --card-bg: rgba(255, 255, 255, 0.04);
    --card-hover: rgba(255, 255, 255, 0.07);
    --border: rgba(255, 255, 255, 0.08);
    --text: #ffffff;
    --text-secondary: rgba(255, 255, 255, 0.65);
    --text-muted: rgba(255, 255, 255, 0.45);
    --blue: #3b82f6;
    --red: #ef4444;
  }

  /* ===== 圆形玻璃态按钮（对齐 demo trigger-icon） ===== */
  .official-btn {
    position: fixed;
    pointer-events: auto;
    z-index: 100;
    width: 44px;
    height: 44px;
    border-radius: 50%;
    border: 1px solid var(--border);
    background: var(--bg-btn);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    color: var(--text);
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: background 0.2s;
  }
  .official-btn:hover {
    background: rgba(255, 255, 255, 0.1);
  }
  .official-btn svg {
    width: 20px;
    height: 20px;
    fill: none;
    stroke: currentColor;
    stroke-width: 2;
    stroke-linecap: round;
    stroke-linejoin: round;
  }
  .official-btn-back {
    top: 14px;
    left: 14px;
  }
  .official-btn-fullscreen {
    top: 14px;
    right: 14px;
  }

  /* ===== Toast 容器（垂直堆叠，多 toast 并存） ===== */
  .official-toast-container {
    position: fixed;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 8px;
    pointer-events: none;
    z-index: 400;
  }

  /* ===== Toast 单条（对齐 demo 玻璃态） ===== */
  .official-toast {
    position: relative;
    background: var(--bg);
    backdrop-filter: blur(16px);
    -webkit-backdrop-filter: blur(16px);
    border: 1px solid var(--border);
    border-radius: 12px;
    color: var(--text);
    padding: 12px 24px;
    font-size: 14px;
    font-weight: 500;
    box-shadow: 0 16px 48px rgba(0, 0, 0, 0.4);
    white-space: nowrap;
    opacity: 0;
    transform: translateY(16px) scale(0.95);
    animation: official-toast-in 0.3s cubic-bezier(0.16, 1, 0.3, 1) forwards;
    transition: opacity 0.25s cubic-bezier(0.7, 0, 0.84, 0),
                transform 0.25s cubic-bezier(0.7, 0, 0.84, 0);
  }

  /* Toast 退出态（JS 添加 class 触发） */
  .official-toast.leaving {
    opacity: 0;
    transform: translateY(-12px) scale(0.96);
  }

  /* ===== Confirm 对话框（对齐 demo 玻璃态面板） ===== */
  .official-confirm-overlay {
    position: fixed;
    inset: 0;
    pointer-events: auto;
    z-index: 350;
    display: flex;
    align-items: center;
    justify-content: center;
    background: rgba(0, 0, 0, 0.5);
    backdrop-filter: blur(4px);
    -webkit-backdrop-filter: blur(4px);
    animation: official-fade-in 0.15s ease;
  }
  .official-confirm-dialog {
    background: var(--bg);
    backdrop-filter: blur(16px);
    -webkit-backdrop-filter: blur(16px);
    border: 1px solid var(--border);
    border-radius: 16px;
    padding: 24px;
    min-width: 300px;
    max-width: 400px;
    color: var(--text);
    box-shadow: 0 16px 48px rgba(0, 0, 0, 0.4);
  }
  .official-confirm-title {
    margin: 0 0 8px;
    font-size: 16px;
    font-weight: 600;
  }
  .official-confirm-content {
    margin: 0 0 20px;
    font-size: 14px;
    line-height: 1.5;
    color: var(--text-secondary);
  }
  .official-confirm-actions {
    display: flex;
    gap: 8px;
    justify-content: flex-end;
  }
  .official-confirm-btn {
    padding: 10px 20px;
    border: none;
    border-radius: 8px;
    font-size: 14px;
    font-weight: 500;
    cursor: pointer;
    transition: background 0.15s;
  }
  .official-confirm-btn-cancel {
    background: rgba(255, 255, 255, 0.06);
    border: 1px solid var(--border);
    color: var(--text);
  }
  .official-confirm-btn-cancel:hover {
    background: rgba(255, 255, 255, 0.1);
  }
  .official-confirm-btn-ok {
    background: #fff;
    color: #000;
  }
  .official-confirm-btn-ok:hover {
    background: rgba(255, 255, 255, 0.9);
  }

  /* ===== Debug 面板（对齐 demo 暗色玻璃态） ===== */
  .official-debug {
    position: fixed;
    bottom: 14px;
    left: 14px;
    pointer-events: none;
    z-index: 200;
    background: var(--bg);
    backdrop-filter: blur(16px);
    -webkit-backdrop-filter: blur(16px);
    border: 1px solid var(--border);
    border-radius: 10px;
    color: var(--text-secondary);
    font: 12px/1.6 ui-monospace, "SF Mono", Menlo, Consolas, monospace;
    padding: 10px 14px;
  }

  /* ===== Animations ===== */
  @keyframes official-fade-in {
    from { opacity: 0; }
    to { opacity: 1; }
  }

  /* Toast 进入：从下方浮起 + 轻微缩放 */
  @keyframes official-toast-in {
    from {
      opacity: 0;
      transform: translateY(16px) scale(0.95);
    }
    to {
      opacity: 1;
      transform: translateY(0) scale(1);
    }
  }

  /* ===== 无障碍：尊重用户减少动画偏好 ===== */
  @media (prefers-reduced-motion: reduce) {
    .official-toast {
      animation: none;
      transition: opacity 0.15s ease;
      opacity: 1;
      transform: none;
    }
    .official-toast.leaving {
      opacity: 0;
      transform: none;
    }
  }
`;
