import { createBoundHost, currentContext } from '@tencent/program-host';
import type { IProgram } from '@tencent/program-host';
import { OFFICIAL_UI_STYLES } from './ui-styles';
import { createDebugPanel } from './debug-panel';
import { createOverlayComponents } from './overlay-components';
import { BACK_ICON_SVG, FULLSCREEN_ICON_SVG } from './icons';

/** 模块级引用，供 dispose() 调用 dispose() 取消 RAF 循环 */
let debugRef: ReturnType<typeof createDebugPanel> | null = null;
/** 模块级引用，供 registerApi 回调访问 overlays */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
let overlaysRef: ReturnType<typeof createOverlayComponents> | null = null;

const official: IProgram = {
  init(): void {
    // ⭐ 创建 bound host — 捕获当前 programId，异步回调（RAF/setTimeout）也能正确路由 context
    const programId = currentContext.active();
    const host = programId ? createBoundHost(programId) : null;
    if (!host) {
      throw new Error('[program-official] init 必须在活跃的 program context 内调用');
    }

    // ⭐ 声明路由表（HUD 只有一个根页面）
    host.router.routes([
      {
        path: '/',
        component: {
          mount(root: HTMLElement): void {
            root.style.cssText = 'position:fixed;inset:0;pointer-events:none;';

            // 注入公共样式（含 design tokens + 玻璃态组件 class）
            const style = document.createElement('style');
            style.textContent = OFFICIAL_UI_STYLES;
            root.appendChild(style);

            // ---- 返回按钮（左上角，圆形玻璃态） ----
            const btnBack = document.createElement('button');
            btnBack.className = 'official-btn official-btn-back';
            btnBack.innerHTML = BACK_ICON_SVG;
            btnBack.onclick = () => {
              host.sdk.ui.exit ? host.sdk.ui.exit() : window.history.back();
            };
            root.appendChild(btnBack);

            // ---- 全屏按钮（右上角，圆形玻璃态） ----
            const btnFullscreen = document.createElement('button');
            btnFullscreen.className = 'official-btn official-btn-fullscreen';
            btnFullscreen.innerHTML = FULLSCREEN_ICON_SVG;
            btnFullscreen.onclick = () => host.sdk.ui.toggleFullscreen();
            root.appendChild(btnFullscreen);

            // ---- Debug 面板（左下角，玻璃态） ----
            const debug = createDebugPanel(root, () => host.sdk.character.getPosition());
            debugRef = debug;

            // ---- Overlay 组件（Toast / Confirm） ----
            overlaysRef = createOverlayComponents(root);
          },
          onUnmount(): void {
            debugRef?.dispose();
            debugRef = null;
            overlaysRef = null;
          },
        },
      },
    ]);

    // ---- 注册 exposedApi ----
    host.registerApi({
      showToast: (msg: string, dur?: number) => overlaysRef?.showToast(msg, dur),
      showConfirm: (opts: { title: string; content: string; onConfirm?: () => void; onCancel?: () => void }) =>
        overlaysRef?.showConfirm(opts),
      setDebugVisible: (visible: boolean) => debugRef?.setVisible(visible),
    });
  },

  dispose(): void {
    debugRef?.dispose();
    debugRef = null;
    overlaysRef = null;
  },
};

export default official;
