/** showConfirm 选项 */
export interface ConfirmOptions {
  title: string;
  content: string;
  onConfirm?: () => void;
  onCancel?: () => void;
}

/**
 * 创建 overlay 组件（在 ShadowRoot 内渲染弹窗/对话框）
 * 返回三个 exposedApi 方法
 */
export function createOverlayComponents(root: HTMLElement): {
  showToast(msg: string, duration?: number): void;
  showConfirm(opts: ConfirmOptions): void;
  setDebugVisible(visible: boolean): void;
} {
  let currentOverlay: HTMLElement | null = null;

  /** Toast 容器（懒创建，垂直堆叠多条 toast） */
  let toastContainer: HTMLElement | null = null;
  const MAX_TOASTS = 5;
  /** 进入动画时长（ms），下一条 toast 须等此时间后再出现 */
  const TOAST_ENTER_MS = 300;
  /** 待显示 toast 队列（逐条入场，避免同时播放动画） */
  const toastQueue: Array<{ msg: string; duration: number }> = [];
  let isProcessingQueue = false;

  /** 获取或创建 toast 容器 */
  function getToastContainer(): HTMLElement {
    if (!toastContainer || !toastContainer.isConnected) {
      toastContainer = document.createElement('div');
      toastContainer.className = 'official-toast-container';
      root.appendChild(toastContainer);
    }
    return toastContainer;
  }

  /** 清除当前弹窗 */
  function clearOverlay(): void {
    if (currentOverlay) {
      currentOverlay.remove();
      currentOverlay = null;
    }
  }

  /** 将单条 toast 追加到容器并启动其独立计时 */
  function appendToast(msg: string, duration: number): void {
    const container = getToastContainer();

    // 超出上限时移除最旧的 toast（同时清理其定时器）
    while (container.children.length >= MAX_TOASTS) {
      const oldest = container.firstChild as HTMLElement | null;
      if (oldest?.dataset.leaveTimer) {
        clearTimeout(Number(oldest.dataset.leaveTimer));
      }
      oldest?.remove();
    }

    const toast = document.createElement('div');
    toast.className = 'official-toast';
    toast.textContent = msg;
    container.appendChild(toast);

    // duration 后触发 CSS 退出动画，transition 结束后移除 DOM
    const leaveTimer = window.setTimeout(() => {
      toast.classList.add('leaving');
      // CSS transition 0.25s，+50ms 余量确保动画播完
      window.setTimeout(() => {
        toast.remove();
        if (toastContainer && toastContainer.children.length === 0) {
          toastContainer.remove();
          toastContainer = null;
        }
      }, 300);
    }, duration);

    toast.dataset.leaveTimer = String(leaveTimer);
  }

  /** 逐条处理 toast 队列：前一条进入动画播完才追加下一条 */
  function processToastQueue(): void {
    if (toastQueue.length === 0) {
      isProcessingQueue = false;
      return;
    }
    isProcessingQueue = true;
    const { msg, duration } = toastQueue.shift()!;
    appendToast(msg, duration);
    // 等进入动画播完，再处理下一条
    window.setTimeout(processToastQueue, TOAST_ENTER_MS);
  }

  /** 显示 Toast 提示（玻璃态，多条逐条入场，各自独立消失） */
  function showToast(msg: string, duration = 2000): void {
    toastQueue.push({ msg, duration });
    if (!isProcessingQueue) {
      processToastQueue();
    }
  }

  /** 显示确认对话框（玻璃态，对齐 demo 设计系统） */
  function showConfirm(opts: ConfirmOptions): void {
    clearOverlay();

    const overlay = document.createElement('div');
    overlay.className = 'official-confirm-overlay';
    overlay.innerHTML = `
      <div class="official-confirm-dialog">
        <h4 class="official-confirm-title">${opts.title}</h4>
        <p class="official-confirm-content">${opts.content}</p>
        <div class="official-confirm-actions">
          <button class="official-confirm-btn official-confirm-btn-cancel">取消</button>
          <button class="official-confirm-btn official-confirm-btn-ok">确认</button>
        </div>
      </div>`;
    overlay.querySelector('.official-confirm-btn-cancel')?.addEventListener('click', () => {
      clearOverlay();
      opts.onCancel?.();
    });
    overlay.querySelector('.official-confirm-btn-ok')?.addEventListener('click', () => {
      clearOverlay();
      opts.onConfirm?.();
    });

    root.appendChild(overlay);
    currentOverlay = overlay;
  }

  /** 设置 Debug 面板可见性 */
  function setDebugVisible(visible: boolean): void {
    // 通过 dom 查找 debug-panel
    const panel = root.querySelector('[data-debug-panel]') as HTMLElement | null;
    if (panel) {
      panel.style.display = visible ? '' : 'none';
    }
  }

  return { showToast, showConfirm, setDebugVisible };
}
