/** 角色位置（RAF 回调中调用，需在 init 时绑定到正确 context） */
type PositionGetter = () => { x: number; y: number; z: number } | null;

/**
 * 创建 Debug 面板（左下角，URL ?debug=1 时显示）
 * 自驱动 RAF 循环更新 FPS + 位置
 *
 * @param getPosition 角色位置获取函数（由调用方在 init 生命周期内绑定 bound host）
 */
export function createDebugPanel(root: HTMLElement, getPosition: PositionGetter): {
  panel: HTMLElement;
  setVisible(v: boolean): void;
  dispose(): void;
} {
  const panel = document.createElement('div');
  panel.className = 'official-debug';
  panel.setAttribute('data-debug-panel', '');
  panel.textContent = 'Debug: FPS —';

  let rafId = 0;
  let frameCount = 0;
  let lastTime = performance.now();
  // hash 路由下 window.location.search 为空，需从 hash fragment 中提取 query params
  const hashQuery = window.location.hash.split('?')[1] || '';
  const isDebug =
    new URLSearchParams(window.location.search).get('debugPanel') === '1' ||
    new URLSearchParams(hashQuery).get('debugPanel') === '1';

  if (isDebug) {
    root.appendChild(panel);

    const tick = () => {
      frameCount++;
      const now = performance.now();
      if (now - lastTime >= 1000) {
        const fps = Math.round(frameCount / ((now - lastTime) / 1000));
        const pos = getPosition();
        panel.textContent =
          `FPS: ${fps} | Pos: ${pos ? `${pos.x.toFixed(1)},${pos.y.toFixed(1)},${pos.z.toFixed(1)}` : '—'}`;
        frameCount = 0;
        lastTime = now;
      }
      rafId = requestAnimationFrame(tick);
    };
    rafId = requestAnimationFrame(tick);
  }

  return {
    panel,
    setVisible(v: boolean) {
      panel.style.display = v ? '' : 'none';
    },
    dispose() {
      if (rafId) cancelAnimationFrame(rafId);
      panel.remove();
    },
  };
}
